"""Build a fully local, read-only design prototype. Python standard library only."""
from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parent
REPO = ROOT.parent.parent
RECORDS = [
    ('B001', 'Worker skips a review-ready entry', 'hooks/worker-routing', 'The worker selection path treats an otherwise eligible needs: review entry as unavailable.', 'Synthetic trace: the entry is open, unblocked, and unclaimed, but the worker returns no work.', 'The worker consumes one shared lifecycle contract and selects the entry.'),
    ('B002', 'Board shows the wrong lane', 'board-view/lifecycle-lanes', 'The HTML renderer places a needs: review entry in the To do lane.', 'Synthetic snapshot: the Markdown state and rendered lane disagree for the same entry.', 'The renderer consumes the shared lifecycle contract and uses the Review lane.'),
    ('B003', 'Ready-work list omits the entry', 'mcp-server/ready-queue', 'The MCP ready queue omits an open, unblocked entry in the same lifecycle state.', 'Synthetic response: the entry is present in the board but absent from ready results.', 'MCP consumes the shared lifecycle contract and returns the eligible entry.'),
]
def icon(name, prefix=''):
    return f'<img class="icon" src="{prefix}assets/icons/{name}.svg" alt="" width="20" height="20">'
def shell(title, body, prefix=''):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><title>{title} · Engineering Board</title><link rel="stylesheet" href="{prefix}style.css"><script src="{prefix}app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-header wrap"><a class="wordmark" href="{prefix}index.html" aria-label="Engineering Board home">engineering board</a><nav aria-label="Main"><a href="{prefix}index.html#example">Example</a><a href="{prefix}index.html#install">Install</a><a href="{prefix}docs.html">Docs</a></nav><button class="theme js-only" type="button" aria-label="Switch to light theme" title="Switch to light theme">{icon('sun',prefix)}</button></header>{body}<footer class="wrap"><span class="wordmark">engineering board</span><p>Design prototype · Synthetic example · Read-only</p><a href="{prefix}docs.html">About this prototype {icon('arrow-up-right',prefix)}</a></footer><p id="announcement" class="sr-only" aria-live="polite" aria-atomic="true"></p></body></html>'''
def facts(rows):
    return '<dl class="facts">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in rows)+'</dl>'
hfacts = [('Evidence','Three findings share a lifecycle-state pattern.'),('Alternative','Independent filtering errors.'),('Falsifier','All adapters use the same rule.'),('Outcome','No outcome recorded.')]
def finding_link(record, diagram=False):
    id,title,path,*_=record
    return f'<a class="{"diagram-finding" if diagram else "finding"}" href="#entry-{id}" data-select="{id}" data-search="{id} {escape(title)} {path}">{icon("file-text")}<span><span class="record-id">{id}</span><span>{title}</span></span>{"" if diagram else icon("chevron-right")}</a>'
panels = '<article class="record-panel" id="entry-H001" data-panel="H001" tabindex="-1"><div class="record-top"><span class="record-id">H001 / HYPOTHESIS</span><span class="badge">Proposed hypothesis</span></div><h3>Lifecycle rules differ across adapters.</h3>'+facts(hfacts)+'<div class="record-bottom"><span>Inspect the sources before selecting a fix.</span><a href="source/H001.html">Open source record '+icon('arrow-up-right')+'</a></div></article>'
for id,title,path,observation,evidence,done in RECORDS:
    panels += f'<article class="record-panel" id="entry-{id}" data-panel="{id}" tabindex="-1"><div class="record-top"><span class="record-id">{id} / FINDING</span><span class="badge">Open · Synthetic</span></div><h3>{title}</h3>'+facts([('Affects',f'<code>{path}</code>'),('Observed',escape(observation)),('Evidence',escape(evidence)),('Next action','Inspect the adapter’s lifecycle rule and compare it with the same review-ready state in the other adapters.')])+f'<div class="record-bottom"><a href="#entry-H001" data-select="H001">View proposed hypothesis</a><a href="source/{id}.html">Open source record {icon("arrow-up-right")}</a></div></article>'
install_commands='codex plugin marketplace add GhostlyGawd/engineering-board\ncodex plugin add engineering-board@engineering-board'
prompt='Initialize Engineering Board in this repository and show me the board location.'
body='''<main id="main"><section class="hero wrap" aria-labelledby="hero-title"><div class="hero-copy"><h1 id="hero-title">Connect findings.<br>Inspect the evidence.</h1><p class="hero-description">Repository memory for engineering agents.</p><div class="hero-actions"><a class="button" href="#install">Start with Codex '''+icon('arrow-up-right')+'''</a><a class="text-link" href="#example">Explore example</a></div><div class="first-use"><p><span>First use</span>Ask Codex to initialize Engineering Board in this repository.</p><p><span>Expected result</span>A repository-owned Markdown board.</p></div></div><div class="relationship" role="group" aria-label="Three synthetic findings linked to one proposed hypothesis"><p class="eyebrow">Synthetic example · Read-only</p><div class="relationship-grid"><div class="diagram-findings">'''+''.join(finding_link(r,True) for r in RECORDS)+'''</div><div class="connector" aria-hidden="true"><span></span><span></span><span></span></div><div class="diagram-result"><a class="hypothesis" href="#entry-H001" data-select="H001"><span class="badge">Proposed hypothesis</span><span class="record-id">H001</span><strong>Lifecycle rules differ<br>across adapters.</strong></a><p>Three findings.<br>One pattern to investigate.</p></div></div></div></section><section class="example-section" id="example" aria-labelledby="example-title"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">01 / Follow the evidence</p><h2 id="example-title">Synthetic example <span>Read-only</span></h2></div><a class="text-link" href="source/H001.html">Open hypothesis source '''+icon('arrow-up-right')+'''</a></div><div class="investigation"><aside class="findings-panel" aria-label="Findings"><div class="findings-heading"><h3>Findings <span>03</span></h3><a href="#entry-H001" data-select="H001">Overview</a></div><form class="search js-only" role="search"><label class="sr-only" for="finding-search">Search findings by ID, title, or path</label>'''+icon('search')+'''<input id="finding-search" type="search" placeholder="Search findings" autocomplete="off"><button type="reset" aria-label="Clear search" title="Clear search">'''+icon('x')+'''</button></form><div class="finding-list">'''+''.join(finding_link(r) for r in RECORDS)+'''</div><div class="no-results" hidden><p>No matching findings.</p><button type="button" class="text-link" data-reset>Clear search</button></div><p class="list-note">A shared pattern is a starting point.<br>The source records carry the evidence.</p></aside><div class="record-container">'''+panels+'''</div></div></div></section><section class="install wrap" id="install" aria-labelledby="install-title"><div class="install-intro"><p class="eyebrow">02 / Start in your repository</p><h2 id="install-title">Your first board.<br>A lasting record.</h2><p>Install the plugin in Codex, then start a new session in your repository. Your board lives alongside your code.</p><p class="muted">These commands run in your own terminal. This prototype cannot install or change your repository.</p></div><div class="install-steps"><article><span class="step">01</span><h3>Add the Codex plugin</h3><div class="code-block"><pre id="install-command">'''+escape(install_commands)+'''</pre><button type="button" class="copy js-only" data-copy="install-command" aria-label="Copy installation commands">'''+icon('copy')+''' Copy</button></div><p>You need Codex CLI and Python 3 available on your machine.</p></article><article><span class="step">02</span><h3>Start a new Codex session</h3><p>Open the repository you want to use, then ask:</p><div class="prompt-block"><p id="first-prompt">'''+escape(prompt)+'''</p><button type="button" class="copy js-only" data-copy="first-prompt" aria-label="Copy initialization prompt">'''+icon('copy')+''' Copy prompt</button></div></article><article><span class="step">03</span><h3>Check the result</h3><p>Expect a repository-owned Markdown board. Ask Codex to show the board and its location. Then capture a real engineering observation when one arises.</p><details><summary>If the board tools are missing</summary><p>Confirm both installation commands completed, then start a new Codex session. Check that Python 3 is available. Ask Codex whether the Engineering Board MCP server is connected before retrying initialization.</p></details><details><summary>Using Claude Code or another MCP client</summary><p>In Claude Code, run these commands in order:</p><pre>/plugin marketplace add GhostlyGawd/engineering-board\n/plugin install engineering-board\n/board-setup\n/board-demo</pre><p>Other MCP clients use the bundled Python server. See the <a href="docs.html#other-clients">client setup notes</a>.</p></details></article></div></section></main>'''
(ROOT/'index.html').write_text(shell('Connect findings. Inspect the evidence.',body))
for id,title,path,observation,evidence,done in RECORDS:
    fixture = next((REPO/'references/demo/pattern-intelligence/bugs').glob(id+'*.md'))
    raw=fixture.read_text()
    (ROOT/'source'/f'{id}.md').write_text(raw)
    content=f'<main id="main" class="source-page wrap"><a class="text-link" href="../index.html#entry-{id}">{icon("arrow-left","../")} Back to finding</a><p class="eyebrow">Synthetic example · Read-only</p><div class="record-top"><span class="record-id">{id} / SOURCE RECORD</span><span class="badge">Open</span></div><h1>{title}</h1><p class="source-intro">Source: <code>references/demo/pattern-intelligence/bugs/{fixture.name}</code></p>'+facts([('Affects',f'<code>{path}</code>'),('Observed behavior',escape(observation)),('Evidence',escape(evidence)),('Done when',escape(done))])+f'<p>Related claim: <a href="H001.html">H001 · Lifecycle rules differ across adapters</a>. This relationship is a proposal, not a confirmed cause.</p><details><summary>Read the original Markdown</summary><pre>{escape(raw)}</pre></details><p><a href="{id}.md" download>Download source Markdown {icon("arrow-up-right","../")}</a></p></main>'
    (ROOT/'source'/f'{id}.html').write_text(shell(f'{id} source',content,'../'))
hraw='''---
id: H001
type: hypothesis
status: proposed
tags: [synthetic-demo]
sources: [B001, B002, B003]
---
# Lifecycle rules differ across adapters

## Evidence
Three findings share a lifecycle-state pattern.

## Alternative
Independent filtering errors.

## Falsifier
All adapters use the same rule.

## Outcome
No outcome recorded.

## Next action
Compare the worker, renderer, and MCP lifecycle rules against the same review-ready state. Record whether this supports or rejects the proposal.
'''
(ROOT/'source/H001.md').write_text(hraw)
hcontent='<main id="main" class="source-page wrap"><a class="text-link" href="../index.html#entry-H001">'+icon('arrow-left','../')+' Back to investigation</a><p class="eyebrow">Synthetic example · Read-only</p><div class="record-top"><span class="record-id">H001 / SOURCE RECORD</span><span class="badge">Proposed hypothesis</span></div><h1>Lifecycle rules differ across adapters.</h1><p class="source-intro">An illustrative hypothesis connecting the three bundled synthetic findings. No confirmed cause or product outcome is claimed.</p>'+facts(hfacts)+'<h2>Supporting records</h2><ul class="source-links">'+''.join(f'<li><a href="{id}.html"><span class="record-id">{id}</span> {title} {icon("arrow-up-right","../")}</a></li>' for id,title,*_ in RECORDS)+'</ul><h2>Next action</h2><p>Compare the worker, renderer, and MCP lifecycle rules against the same review-ready state. Record whether this supports or rejects the proposal.</p><details><summary>Read the original Markdown</summary><pre>'+escape(hraw)+'</pre></details><p><a href="H001.md" download>Download source Markdown '+icon('arrow-up-right','../')+'</a></p></main>'
(ROOT/'source/H001.html').write_text(shell('H001 source',hcontent,'../'))
docs='''<main id="main" class="source-page wrap"><p class="eyebrow">Prototype guide · Synthetic example · Read-only</p><h1>Evidence you can<br>follow back.</h1><p class="source-intro">Engineering Board keeps engineering findings, proposed root causes, and recorded outcomes in repository-owned Markdown.</p><h2>Explore the example</h2><p><a href="index.html#example">Open the investigation</a>, select a finding, and follow its source record. H001 is a proposed explanation. The alternative and falsifier keep uncertainty visible; no outcome is recorded.</p><h2>Begin with Codex</h2><p>Follow the <a href="index.html#install">installation instructions</a>. Initialization creates a board; capturing saves a finding to the inbox. Ask Codex to preview promotion before creating a durable board entry. Ask for relevant repository memory before choosing a fix, and record the observed result afterward.</p><h2 id="other-clients">Other clients</h2><p>Claude Code installation commands are available in the <a href="index.html#install">installation section</a>. For other MCP clients, obtain the Engineering Board repository and use its documented Python server configuration. Every bundled-plugin tool call targets an absolute repository path.</p><p>The authoritative setup guide is the repository README. <a href="https://github.com/GhostlyGawd/engineering-board#readme">Read the upstream README (requires internet)</a>.</p><h2>About this prototype</h2><p>This is a local design prototype, not a connected board. The B001–B003 records are copied from the repository’s synthetic pattern-intelligence fixtures. H001 is an illustrative proposed hypothesis. Example links work offline and without JavaScript. Search, inline selection, copy, and theme switching are progressive enhancements.</p><p>No board data, installation state, analytics, or user accounts are connected.</p></main>'''
(ROOT/'docs.html').write_text(shell('Guide',docs))
print('Built six static HTML pages and four source records.')
